        var canvas = document.getElementById('canvas');
        var ctx = canvas.getContext('2d');
        var initialAngle = 45;
        var released = false;

        document.getElementById('start-button').addEventListener('click', function() {
            released = true;
        });

        function update() {
            if (released) {
                var g = 0.98; // acceleration due to gravity
