            ctx.arc(canvas.width / 2, canvas.height / 2, 50, -Math.PI / 2, -theta);
            ctx.moveTo(canvas.width / 2, canvas.height / 2);
            ctx.lineTo(canvas.width / 2, canvas.height / 2 - 100);
